#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <filesystem>
#include <string>
#include "../loader/windows/host_sandbox.h"
int wmain(int argc,wchar_t **argv){if(argc!=4)return 64;try{namespace fs=std::filesystem;auto host=fs::canonical(argv[1]);auto profile=fs::absolute(argv[2]);auto core=fs::canonical(argv[3]);fs::create_directories(profile);host_sandbox::State state;state.prepare(host,profile,core,false);host_sandbox::common_resources(state.data);host_sandbox::grant_tree(state.data,state.sid,FILE_ALL_ACCESS,true);state.allow_firmware();SECURITY_CAPABILITIES caps{};caps.AppContainerSid=state.sid;caps.Capabilities=&state.firmware;caps.CapabilityCount=1;if(!UpdateProcThreadAttribute(state.attributes,0,PROC_THREAD_ATTRIBUTE_SECURITY_CAPABILITIES,&caps,sizeof caps,nullptr,nullptr))return 65;SetEnvironmentVariableW(L"OPEN_SV2_LOADER_DATA_DIR",profile.c_str());std::wstring cmd=L"\""+state.host.wstring()+L"\"";STARTUPINFOEXW start{};start.StartupInfo.cb=sizeof start;start.lpAttributeList=state.attributes;PROCESS_INFORMATION pi{};if(!CreateProcessW(state.host.c_str(),cmd.data(),nullptr,nullptr,TRUE,EXTENDED_STARTUPINFO_PRESENT|CREATE_NO_WINDOW,nullptr,state.host.parent_path().c_str(),&start.StartupInfo,&pi))return 66;WaitForSingleObject(pi.hProcess,10000);DWORD code=0;GetExitCodeProcess(pi.hProcess,&code);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return static_cast<int>(code);}catch(...){return 67;}}
